INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62520, 'spa', 'El sentido primario de sustitución e intercambio, que abarca 16 de 22 ocurrencia', 'El sentido primario de sustitución e intercambio, que abarca 16 de 22 ocurrencias. En Mt 5:38, la ley del talión se enuncia con ἀντί: ''ojo por ojo, diente por diente,'' donde cada pena refleja y sustituye la lesión. Mt 17:27 lo usa para intercambio monetario: la moneda ''por'' Jesús y Pedro. En español, ''en lugar de'' y ''a cambio de'' confirman la lectura de reemplazo. El peso teológico de este sentido alcanza su cumbre en Mt 20:28 y Mc 10:45.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62524, 'spa', 'El uso causal, casi siempre en la construcción fija ἀνθ᾽ ὧν (''por cuanto,'' ''porq', 'El uso causal, casi siempre en la construcción fija ἀνθ᾽ ὧν (''por cuanto,'' ''porque''), que aparece 5 veces. Lucas 1:20 es paradigmático: Zacarías quedará mudo ἀνθ᾽ ὧν no creyó. Lucas 19:44 y Hechos 12:23 introducen igualmente el juicio divino con esta fórmula causal. En español, ''porque'' y ''por cuanto'' marcan una clara separación del patrón de sustitución-reemplazo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62528, 'spa', 'Un sentido acumulativo o sucesivo único, presente solo en Juan 1', 'Un sentido acumulativo o sucesivo único, presente solo en Juan 1:16: χάριν ἀντὶ χάριτος, ''gracia sobre gracia.'' Aquí ἀντί no significa ''en lugar de'' sino más bien ''añadida a'' o ''en sucesión de,'' describiendo gracia que se acumula sobre gracia como olas procedentes de la plenitud de Cristo. El contexto exige la lectura clásica más infrecuente de acumulación en lugar de sustitución.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62531, 'spa', 'Adversario, oponente', 'Adversario u oponente, enraizado en la terminología legal para una parte en un litigio, pero usado ampliamente para designar a cualquier figura hostil. En Mt 5:25 y Lc 12:58 el contexto forense es explícito — ponte de acuerdo con tu ἀντίδικος antes de llegar al juez. La súplica de la viuda en Lc 18:3 amplía el uso a un opresor general, y 1 Pe 5:8 lo aplica al diablo mismo como adversario espiritual supremo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62535, 'spa', 'Oponerse, ser adversario', 'Oponerse, estar en contra como adversario, describiendo hostilidad activa o resistencia dirigida contra personas, enseñanzas o realidades espirituales. En Lc 13:17 y 21:15, «los que se oponen» (ἀντικείμενοι) son adversarios de Jesús y sus seguidores; en 1 Co 16:9 Pablo habla de «muchos adversarios» en Éfeso; Gá 5:17 describe la carne y el Espíritu como «opuestos entre sí»; Fil 1:28 se refiere a los que se oponen a los creyentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62543, 'spa', 'Socorrer y asistir', 'Transmite la idea de ayudar o sostener, a menudo con el matiz de agarrar activamente para auxiliar. Lucas 1:54 alaba a Dios por haber «socorrido» (ἀντελάβετο) a Israel, eco de las promesas proféticas. Hechos 20:35 cita a Jesús sobre la necesidad de «ayudar» a los débiles. En 1 Timoteo 6:2, los amos creyentes «reciben» (ἀντιλαμβανόμενοι) el servicio de buena voluntad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62544, 'spa', 'Hablar en oposicion a alguien o algo, contradecir, negar u objetar activamente l', 'Hablar en oposicion a alguien o algo, contradecir, negar u objetar activamente lo que se dice o propone. Este sentido dominante (9 ocurrencias) aparece en escenarios de confrontacion: los lideres judios incapaces de contradecir la sanacion del cojo (Hch 4:14), los judios de Pisidia que ''contradecian las cosas dichas por Pablo'' (Hch 13:45), y la advertencia a Pilato de que quien libera a Jesus habla contra Cesar (Jn 19:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62549, 'spa', 'Ser objeto de contradiccion u oposicion, expresado mediante la voz pasiva o medi', 'Ser objeto de contradiccion u oposicion, expresado mediante la voz pasiva o media, indicando que el sujeto es quien recibe la contradiccion y no quien la ejerce. Solo 2 ocurrencias claras, pero ambas son teologicamente significativas: la profecia de Simeon sobre el nino Jesus como ''senal de contradiccion'' (Lc 2:34) anticipa todo el arco de rechazo que narraran los Evangelios, y el reconocimiento de Pablo en Roma de que el cristianismo es ''contradicho en todas partes'' (Hch 28:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62556, 'spa', 'Contradicción o disputa', 'Disputa, contradicción u oposición verbal: el acto de hablar o argumentar en contra de una posición. Hebreos 6:16 lo usa para disputas resueltas mediante juramento; Hebreos 7:7 lo emplea como recurso retórico (''fuera de toda contradicción''). El español ''contradicción'' y el alemán ''Widerspruch'' conservan el sentido etimológico de contra-discurso, confirmando este como el significado base.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62560, 'spa', 'Recompensa y reciprocidad', 'Romanos usa ἀντιμισθία para las consecuencias intrínsecas recibidas del error moral: una recompensa inherente a la acción misma. El uso de Pablo en 2 Corintios solicita afecto recíproco: ''como justa retribución, ensanchen también sus corazones''. El mismo sustantivo abarca tanto la recompensa judicial (Romanos) como la reciprocidad relacional (Corintios). El acusativo ἀντιμισθίαν sugiere esto como algo que se recibe o se solicita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62561, 'spa', 'La ciudad de Antioquía (Ἀντιόχεια), que se refiere a Antioquía de Siria — la gra', 'La ciudad de Antioquía (Ἀντιόχεια), que se refiere a Antioquía de Siria — la gran metrópolis donde floreció el cristianismo gentil y donde los creyentes fueron llamados cristianos por primera vez (Hechos 11:26) — o a Antioquía de Pisidia en Asia Menor, una parada en el primer viaje misionero de Pablo (Hechos 13:14; 14:19). El español ''Antioquía'' conserva el nombre clásico a través de las tradiciones de traducción bíblica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62565, 'spa', 'Evasión deliberada', 'La parábola de Jesús usa ἀντιπαρῆλθεν dos veces para describir a líderes religiosos que ven al hombre herido pero activamente evitan ayudar cruzando al lado opuesto del camino. Esto no es un fallo pasivo de notar sino evasión deliberada: elegir distancia sobre involucramiento. El prefijo compuesto ἀντι- enfatiza lo opuesto: no simplemente pasan de largo; pasan al lado opuesto. La acción repetida por ambos sacerdotes marca el contraste con la compasión del samaritano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62571, 'spa', 'Oponerse, resistir', 'Oponerse, resistir o disponerse en contra, frecuentemente con la fuerza de una hostilidad deliberada y personal. La voz media subraya la participación activa en la oposición. En Ro 13:2 la resistencia a la autoridad civil se equipara con resistir la disposición de Dios. En Stg 4:6 y 1 Pe 5:5, Dios mismo ''se dispone contra'' los soberbios — una imagen militar impactante. Hch 18:6 muestra a los oponentes de Pablo resistiendo activamente su mensaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62572, 'spa', 'Figura correspondiente terrenal', 'Los dos usos neotestamentarios establecen vocabulario de antitipo para entender cómo las realidades terrenales corresponden a las celestiales. Hebreos lo usa para el tabernáculo: una copia del santuario verdadero. Pedro lo usa para el bautismo: que corresponde a la salvación del arca por agua. El adjetivo ἀντίτυπος describe no mera similitud sino correspondencia intencional donde la figura terrenal representa y apunta hacia la realidad celestial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62573, 'spa', 'Anticristo / engañador', 'Quien se opone a Cristo o reclama falsamente su identidad, abarcando tanto una figura profetizada del fin de los tiempos como engañadores actuales que niegan la encarnación. En 1 Jn 2:18 el singular «el anticristo viene» coexiste con el plural «muchos anticristos han surgido», mostrando un uso tanto específico como categorial. 1 Jn 2:22 define al anticristo como aquel que niega la relación Padre-Hijo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62574, 'spa', 'Sacar agua', 'Sacar agua de un pozo, cisterna o recipiente. Acción concreta y cotidiana que aparece exclusivamente en Juan. En Caná, los sirvientes sacan agua y descubren vino (Juan 2:8-9); en Sicar, la mujer saca del pozo de Jacob (Juan 4:7, 15). La evidencia interlingüística — español ''sacar'', francés ''puiser'', alemán ''schöpfen'' — confirma un único sentido de extraer líquido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62577, 'spa', 'Sin agua, árido', 'Sin agua, árido: describe una región literalmente seca. En la parábola de Jesús sobre el espíritu inmundo (Matt 12:43; Luke 11:24), el demonio expulsado recorre ''lugares secos'', evocando la antigua asociación del Cercano Oriente entre los páramos desérticos y la desolación espiritual y la morada demoníaca. El castellano ''sin agua'' calca directamente la forma privativa griega.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62578, 'spa', 'Sin hipocresía', 'Genuino, sincero, sin hipocresía ni fingimiento — adjetivo alfa privativo (ἀ + ὑποκριτός, «que no actúa un papel») aplicado a las virtudes cristianas fundamentales. Romanos 12:9 exige que el amor (ἀγάπη) sea ἀνυπόκριτος. Segunda Corintios 6:6 lo incluye entre las credenciales apostólicas de Pablo. Primera Timoteo 1:5 y 2 Timoteo 1:5 lo aplican a la fe, y Santiago 3:17 a la sabiduría celestial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62583, 'spa', 'Insubordinado, rebelde', 'Insubordinado, indisciplinado, rebelde: describe a personas que rehúsan someterse a la autoridad legítima. En 1 Tim 1:9 se lista a los ''insubordinados'' junto a los inicuos; Titus 1:6 exige que los hijos de los ancianos no sean acusados de indisciplina; Titus 1:10 advierte sobre ''muchos contumaces''. El término subraya la desobediencia deliberada como rasgo definitorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62584, 'spa', 'Arriba, hacia arriba', 'Adverbio que indica posición espacial («arriba», «en lo alto») o dirección ascendente, frecuentemente extendido para designar el ámbito celestial o divino en contraste con lo terrenal. En Jn 2:7 es puramente espacial («hasta el borde»), pero en Jn 8:23 Jesús contrasta ser «de arriba» con ser «de abajo», y Gálatas 4:26 habla de «la Jerusalén de arriba». Hechos 2:19 lo emplea para señales celestiales, y Colosenses 3:1-2 urge a buscar las cosas de arriba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62587, 'spa', 'Sala de la Última Cena', 'Tanto Marcos como Lucas describen el mismo cuarto: un gran espacio superior preparado para la comida de Pascua donde Jesús transforma la fiesta en comunión cristiana. El acusativo ἀνάγαιον aparece en frases idénticas: ''Él les mostrará un gran aposento alto amueblado''. Este aposento alto se convierte en espacio sagrado en la memoria cristiana: el lugar de la Última Cena y probablemente el mismo cuarto donde el Jesús resucitado se apareció a los discípulos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62588, 'spa', 'De arriba, del cielo', 'De arriba, del cielo. Sentido espacial: de lo alto, desde el cielo. El sentido principal en el NT, que abarca el velo del templo rasgado desde arriba (Mt 27:51; Mr 15:38), la autoridad de Jesus dada desde arriba (Jn 19:11), la sabiduria de lo alto (Stg 3:15, 17) y el celebre nacimiento de lo alto en Jn 3:3, 7.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62589, 'spa', 'Desde el principio, desde antiguo', 'Desde el principio, desde antiguo. Sentido temporal: desde el comienzo, desde los primeros tiempos. En Hch 26:5, Pablo dice que los judios lo conocen desde el principio, es decir, desde su juventud. Lucas 1:3 tambien lo usa para investigar las cosas desde su origen.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62591, 'spa', 'De nuevo, otra vez', 'De nuevo, otra vez. Sentido iterativo: nuevamente, una vez mas. En Galatas 4:9, Pablo pregunta por que los creyentes quieren servir a los debiles elementos otra vez. Este sentido se superpone con el espacial en Jn 3:3 (nacer de lo alto o de nuevo), creando la productiva ambiguedad sobre la que Nicodemo tropieza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62593, 'spa', 'Posición superior literal y textual', 'El Jesús de Lucas enseña humildad aconsejando a los invitados tomar asientos inferiores, para que el anfitrión pueda invitarlos más arriba: ''Sube más arriba'' usando este comparativo. Hebreos usa ἀνώτερον para referirse a una cita previa en el argumento: ''lo que se dijo arriba''. El comparativo neutro funciona adverbialmente en ambos contextos: literalmente más alto (honor espacial) y arriba (ubicación textual). Esto muestra cómo un solo comparativo abarca elevación física y referencia literaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62594, 'spa', 'Inútil religiosamente', 'Tito usa el plural femenino ἀνωφελεῖς para describir disputas religiosas—son improductivas, no producen beneficio espiritual alguno. Hebreos emplea el mismo adjetivo para la ley mosaica respecto al sacerdocio—era inútil en cuanto no podía perfeccionar a los adoradores. Ambos usos involucran sistemas o prácticas religiosas que fallan en cumplir su propósito aparente. El adjetivo no significa que estas cosas sean malignas, sino que carecen de eficacia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62595, 'spa', 'Imagen de juicio inminente', 'Juan el Bautista usa ἀξίνη como imagen profética de juicio inminente. El hacha no se está acercando; ya está posicionada en la raíz del árbol—el juicio está listo para caer. La imagen advierte que la profesión sin fruto lleva a ser cortado y arrojado al fuego. Tanto Mateo como Lucas preservan palabras idénticas: ''Ya el hacha está puesta a la raíz de los árboles.'' Esta imagen vívida hace el juicio concreto e inminente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62596, 'spa', 'Adjetivo evaluativo', 'Adjetivo evaluativo: una persona o cosa que está a la altura de un estándar de honor, recompensa o condenación. Jesús lo emplea para establecer el umbral de hospitalidad (Mt 10:11, 13). Pablo lo extiende a la exhortación moral: ''andad como es digno de la vocación'' (Ef 4:1). En sentido judicial, ''merecedor de castigo'' (Lc 23:15; Hch 25:11). El ''digno es el Cordero'' de Apocalipsis (5:12) constituye la aplicación positiva suprema.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62598, 'spa', 'Ser tenido por digno', 'Ser considerado digno o juzgado merecedor en voz pasiva o media, expresando un veredicto emitido sobre el sujeto por otra autoridad. Las ocurrencias se agrupan en torno al juicio evaluativo de Dios: los tesalonicenses a quienes Pablo pide que Dios «tenga por dignos de su llamamiento» (2 Ts 1:11), ancianos «considerados dignos de doble honor» (1 Ti 5:17), Jesús «tenido por digno de mayor gloria que Moisés» (He 3:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62600, 'spa', 'Considerar digno', 'Considerar digno, estimar apropiado o juzgar conveniente en voz activa, donde el sujeto ejerce un juicio deliberado sobre el mérito o la idoneidad de alguien. El centurión en Lucas 7:7 declara «no me tuve por digno» (οὐκ ἐμαυτὸν ἠξίωσα) de acercarse a Jesús. En Hechos 15:38 Pablo «no consideró conveniente» (ἠξίου) llevar a Marcos. En Hechos 28:22 los judíos de Roma dicen «consideramos oportuno» escuchar a Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62605, 'spa', 'Dignamente', 'De manera digna de, como conviene — adverbio que exhorta a una conducta acorde con el peso o la dignidad de una persona, vocación o realidad. De ἄξιος («de igual peso en la balanza»), transmite proporcionalidad: la vida de uno debe equilibrarse con el valor de lo recibido. Romanos 16:2 lo aplica a la hospitalidad: recibir a Febe «como es digno de los santos». Efesios 4:1, Filipenses 1:27, Colosenses 1:10 y 1 Tesalonicenses 2:12 lo usan para la conducta cristiana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62606, 'spa', 'Invisible, no perceptible', 'Invisible, que no puede verse con los ojos físicos; usado en el NT exclusivamente para la realidad y los atributos divinos. Ro 1:20 crea una paradoja llamativa: las «cosas invisibles» de Dios se «perciben claramente» mediante el orden creado. Col 1:15 llama a Cristo «imagen del Dios invisible», mientras Col 1:16 contrasta los ámbitos visible e invisible de la creación. 1 Ti 1:17 incluye la invisibilidad entre los atributos divinos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62607, 'spa', 'Informar o dar noticias — el sentido primario y más frecuente', 'Informar o dar noticias — el sentido primario y más frecuente: traer un informe, transmitir noticias o información. Un mensajero o testigo cuenta a alguien lo que sucedió: los porqueros gadarenos ''informaron'' a la ciudad (Mt 8:33), Jesús dice a los discípulos de Juan ''informad lo que oís y veis'' (Mt 11:4), y las mujeres corren a ''anunciar'' el sepulcro vacío (Mt 28:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62613, 'spa', 'Proclamar o anunciar públicamente — un sentido más público y autoritativo', 'Proclamar o anunciar públicamente — un sentido más público y autoritativo: proclamar o anunciar, a menudo con peso teológico. Mt 12:18 cita a Isaías: ''anunciará justicia a las naciones''. Jesús promete ''os anunciaré abiertamente acerca del Padre'' (Jn 16:25). Pablo ''anunció'' la necesidad de arrepentimiento (Hch 26:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62628, 'spa', 'Ser informado — la voz pasiva', 'Ser informado — la voz pasiva: recibir un informe, que se le comunique información a uno. En Lc 8:20, a Jesús ''se le anunció'' que su madre y hermanos estaban afuera. Es una extensión gramatical directa del sentido activo hacia la recepción pasiva de noticias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62630, 'spa', 'Llevar o sacar a una persona, típicamente bajo arresto o custodia, de un lugar a', 'Llevar o sacar a una persona, típicamente bajo arresto o custodia, de un lugar a otro. Este sentido dominante (11 ocurrencias) se concentra en los relatos de la Pasión: Jesús es llevado ante el sumo sacerdote (Mateo 26:57; Marcos 14:53), ante Pilato (Mateo 27:2) y afuera para la crucifixión (Mateo 27:31; Marcos 15:16). El español ''llevar/llevaron'' codifica el movimiento forzado y custodiado de un prisionero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62631, 'spa', 'Una extensión figurada donde un camino ''conduce'' a algún lugar, usada exclusivam', 'Una extensión figurada donde un camino ''conduce'' a algún lugar, usada exclusivamente en la enseñanza de Jesús sobre los dos caminos: ''ancha es la puerta y espacioso el camino que lleva a la perdición'' y ''estrecha es la puerta y angosto el camino que lleva a la vida'' (Mateo 7:13-14). El español ''que lleva'' desplaza el enfoque de la persona como objeto al destino como meta del recorrido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62633, 'spa', 'Formas pasivas que expresan ser llevado o arrastrado, ya sea físicamente a la ej', 'Formas pasivas que expresan ser llevado o arrastrado, ya sea físicamente a la ejecución (Hechos 12:19, donde los guardias son ''llevados'' para ser ejecutados) o figuradamente por falsas enseñanzas (1 Corintios 12:2, ''erais arrastrados a los ídolos mudos''). El sentido de movimiento involuntario bajo una fuerza externa se preserva en las construcciones pasivas del español: ''siendo llevados'', ''siendo arrastrados''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62640, 'spa', 'Quitar por la fuerza', 'Aparece exclusivamente en la enseñanza de Jesús sobre el esposo que será «quitado» (ἀπαρθῇ). Este subjuntivo aoristo pasivo se repite idénticamente en las tres versiones sinópticas (Mateo 9:15; Marcos 2:20; Lucas 5:35), anticipando una remoción violenta que inaugurará un tiempo de ayuno. La imagen transmite una separación forzosa que deja vacío y lamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62641, 'spa', 'Exigir devolución', 'El Jesús de Lucas enseña generosidad radical: cuando alguien toma lo tuyo, no lo reclames de vuelta—usando el imperativo ἀπαίτει. El mismo verbo aparece en el juicio de Dios sobre el rico insensato: ''Te reclaman tu alma''—el plural impersonal sugiere agencia divina. El verbo vincula la generosidad humana y la rendición de cuentas divina. Los humanos no deben reclamar bienes terrenales; Dios reclamará el alma. El tiempo presente indica urgencia inmediata.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62643, 'spa', 'Liberar y soltar', 'Expresa tanto la liberación de la esclavitud como la partida física. Lucas 12:58 advierte sobre no lograr «ser soltado» (ἀπηλλάχθαι) de la detención legal. Hechos 19:12 describe las enfermedades «apartándose» (ἀπαλλάσσεσθαι) por el ministerio de Pablo. Hebreos 2:15 proclama el poder de Cristo para «librar» (ἀπαλλάξῃ) de la esclavitud al temor de la muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62644, 'spa', 'Enajenado del pacto', 'Describe de manera constante a quienes estan separados de la vida divina y del pacto. En Efesios 2:12, los gentiles estaban «enajenados» (ἀπηλλοτριωμένοι) de la ciudadania y las promesas de Israel. Efesios 4:18 retrata a los incredulos «enajenados» (ἀπηλλοτριωμένοι) de la vida de Dios por su endurecida ignorancia. Colosenses 1:21 evoca el antiguo estado de los colosenses como «enajenados» (ἀπηλλοτριωμένους) y enemigos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62645, 'spa', 'Ternura botánica estacional', 'Jesús usa ἁπαλός para describir la rama de la higuera ablandándose con nuevo crecimiento—una señal natural de que el verano se aproxima. El adjetivo captura la calidad flexible de brotes frescos emergiendo después de la dormancia invernal. Tanto Mateo como Marcos preservan esta enseñanza parabólica sobre leer señales naturales para discernir tiempos espirituales. El nominativo masculino ἁπαλὸς describe el cambio de estado de la rama—de dura invernal a tierna primaveral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62646, 'spa', 'Encuentro providencial', 'El Jesús de Marcos predice que los discípulos se encontrarán con un hombre llevando agua—una vista distintiva ya que típicamente las mujeres llevaban agua. Lucas describe a diez leprosos encontrándose con Jesús, manteniendo distancia por impureza ritual. Ambos usos involucran encuentros providenciales: el aguador guía a los discípulos al aposento de la Pascua; los leprosos encuentran a Jesús para sanidad. El aoristo ἀπήντησαν (se encontraron) y el futuro ἀπαντήσει (se encontrará) marcan eventos específicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62647, 'spa', 'Salida al encuentro', 'Designa un recibimiento formal en el que se sale a recibir a alguien que se aproxima. Mateo 25:6 lo usa en la parabola del esposo: el clamor convoca al «encuentro» (ἀπάντησιν). Hechos 28:15 describe a los creyentes viajando para «recibir» (ἀπάντησιν) a Pablo. De manera culminante, 1 Tesalonicenses 4:17 lo emplea para el «encuentro» (ἀπάντησιν) escatologico con el Senor en el aire a su regreso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62648, 'spa', 'Una vez', 'Una vez. Adverbio que indica una sola ocurrencia, con dos registros en el NT: (a) el sentido numerico simple de una sola vez en contextos narrativos y epistolares (2 Co 11:25; Fil 4:16; 1 Ts 2:18), y (b) el teologicamente cargado de una vez por todas en Hebreos y Judas, que enfatiza el caracter decisivo e irrepetible de la obra expiatoria de Cristo (He 9:7, 9:26-28, 10:2) y el deposito apostolico de la fe (Jud 3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62652, 'spa', 'Negar, renegar — Negar o renegar de una persona, repudiando toda asociación con ', 'Negar, renegar — Negar o renegar de una persona, repudiando toda asociación con ella, especialmente bajo presión o amenaza. Definido por la triple negación de Pedro de conocer a Jesús la noche de su arresto (Mt 26:34-35, 75; Mr 14:30-31, 72; Lc 22:34, 61). Jesús advirtió que quien lo niegue ante los demás será negado ante el Padre (cf. Mt 10:33 usando ἀρνέομαι).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62657, 'spa', 'Primicias', 'Primicias: la porción inicial y representativa de una cosecha consagrada a Dios, significando que el todo le pertenece. Pablo aplica esta imagen agrícola-sacrificial metafóricamente en varias direcciones: Cristo como primicias de la resurrección garantiza la cosecha plena de creyentes resucitados (1 Co 15:20, 23); el Espíritu Santo como primicias de la gloria futura (Ro 8:23); los primeros convertidos de una región como primicias de la obra misionera (Ro 16:5; 1 Co 16:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62658, 'spa', 'todo, todos, el conjunto entero (cuantificador universal enfático)', 'todo, todos, el conjunto entero (cuantificador universal enfático)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62666, 'spa', 'Enganar o ser enganado', 'Abarca tanto el enganar a otros como el ser enganado uno mismo. Efesios 5:6 advierte: «que nadie os engane» (ἀπατάτω) con argumentos vacios sobre la ira de Dios. Primera Timoteo 2:14 afirma que Eva «fue enganada» (ἠπατήθη), mostrando en voz pasiva su condicion de victima de la astucia de la serpiente. Santiago 1:26 describe el autoengano: quien «engana» (ἀπατῶν) su propio corazon respecto a la verdadera religion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62667, 'spa', 'Engaño, decepción', 'El acto, la práctica o la cualidad de engañar: fraude, astucia, artimañas. Todas las apariciones neotestamentarias expresan un concepto único e indiferenciado de decepción. En Mateo 13:22 y Marcos 4:19 describe la naturaleza seductora de las riquezas; en Efesios 4:22 caracteriza los «deseos engañosos» del viejo hombre; en Colosenses 2:8 Pablo advierte contra la «filosofía y vano engaño»; y en 2 Tesalonicenses 2:10 acompaña al hombre de iniquidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62674, 'spa', 'Desobediencia', 'Desobediencia voluntaria o negativa a creer y obedecer, especialmente ante los mandatos y la revelación de Dios. La evidencia multilingüe es perfectamente uniforme: español «desobediencia», francés «désobéissance», alemán «Ungehorsam», cada una formación privativa que refleja la estructura alfa-privativa del griego. En Ro 11:30 y 11:32 Pablo desarrolla una teología de la desobediencia donde la negativa de Israel se convierte en instrumento de misericordia universal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62676, 'spa', 'Desobedecer, ser desobediente', 'Desobedecer, ser desobediente. Negarse a dejarse persuadir o a someterse a la autoridad, la verdad o el mensaje del evangelio, expresando resistencia voluntaria en lugar de mera ignorancia. Se aplica a los oponentes judios de la mision apostolica (Hch 14:2; 19:9), a la rebelion mas amplia de la humanidad contra Dios (Ro 2:8; 10:21; 11:30-31), a quienes tropiezan con la piedra angular (1 P 2:8; 3:1) y a la generacion antediluviana (1 P 3:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62689, 'spa', 'Desobediente, rebelde', 'Desobediente, rebelde, que rehúsa dejarse persuadir u obedecer, del alfa-privativo ἀ + πειθής («in-persuasible»). Lucas 1:17 lo usa en contexto redentor: convertir a los desobedientes a la mentalidad de los justos. Hechos 26:19 muestra la enfática negación de Pablo de desobediencia a la visión celestial. Las demás ocurrencias aparecen en catálogos de vicios donde caracteriza una vida alejada de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62693, 'spa', 'Proferir amenazas intimidantes', 'Proferir amenazas o hablar palabras destinadas a intimidar, coaccionar o advertir de un daño inminente. Las dos ocurrencias neotestamentarias presentan imágenes contrastantes: Hechos 4:17 muestra a las autoridades religiosas deliberando si amenazar a los apóstoles para silenciarlos (ἀπειλησώμεθα, subjuntivo que expresa deliberación), mientras que 1 Pedro 2:23 elogia a Cristo quien, a pesar de sufrir injustamente, se abstuvo de amenazar (ἠπείλε, imperfecto negativo).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62694, 'spa', 'Amenaza intimidatoria', 'Designa palabras amenazantes destinadas a intimidar o causar dano. Hechos 4:29 registra a los creyentes orando ante las «amenazas» (ἀπειλῶν) de sus adversarios. Hechos 9:1 describe vividamente a Saulo «respirando amenaza» (ἀπειλῆς) y muerte, expresion que revela una hostilidad que impregnaba su propio aliento. Efesios 6:9 ordena a los amos abandonar la «amenaza» (ἀπειλῆς) porque Dios no hace acepcion de personas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62695, 'spa', 'Estar ausente', 'Estar físicamente ausente o lejos de un lugar, grupo o persona. Traducido uniformemente como español «ausente/estando ausente», francés «être absent», alemán «abwesend sein». Casi todos los usos neotestamentarios son paulinos y expresan la tensión entre la distancia física y la autoridad espiritual. En 1 Co 5:3 Pablo está «ausente en cuerpo pero presente en espíritu»; en 2 Co 10:1 sus opositores lo acusan de ser valiente solo por carta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62702, 'spa', 'Aguardar con anhelo', 'Esperar con intenso y ferviente anhelo, particularmente las realidades escatológicas. Cada aparición en el NT apunta al cumplimiento divino: la creación aguardando la manifestación de los hijos de Dios (Rom 8:19), los creyentes esperando la adopción y la redención corporal (Rom 8:23, 25), o la expectativa anhelante del Salvador que vendrá del cielo (Fil 3:20). Las traducciones al español reflejan uniformemente esta mirada hacia adelante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62708, 'spa', 'Despojar completamente', 'Despojar completamente, remover como quien se quita ropa o armadura, usado metafóricamente para transformación espiritual decisiva. Ambas ocurrencias en Colosenses emplean el participio aoristo medio (ἀπεκδυσάμενος, ἀπεκδυσάμενοι), enfatizando acción completada y agencia personal. En 2:15, el sujeto es Cristo desarmando poderes espirituales hostiles: la imagen sugiere un vencedor despojando la armadura de un enemigo derrotado. En 3:9, los creyentes han despojado el ''viejo hombre'' con sus prácticas malvadas, una remoción tan total como quitarse vestiduras contaminadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62715, 'spa', 'Enfrente / contra', 'Preposición que significa «enfrente», «delante de», «en presencia de» o «contra», según el contexto. El sentido espacial se aprecia claramente en Mt 27:61, donde las mujeres se sientan «enfrente» del sepulcro. Mt 27:24 la usa para indicar que Pilato actúa «delante» de la multitud, subrayando la visibilidad pública. Hch 3:16 transmite «en presencia de» testigos. El significado adversativo aflora en Hch 17:7, donde los creyentes actúan «contra» los decretos imperiales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62719, 'spa', 'irse, partir físicamente', 'Irse o partir físicamente de un lugar o persona — el sentido central abrumador con 112 ocurrencias, que cubre el movimiento humano ordinario a lo largo de las secciones narrativas del Nuevo Testamento. En Mt 8:33 los porqueros «se fueron» a la ciudad; en Mt 9:7 el paralítico «se fue» a su casa; en Mt 13:46 el mercader «fue y vendió» todo por la perla de gran precio. El español emplea «se fue» o «partió».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62731, 'spa', 'pasar, terminar', 'De cosas, condiciones o épocas que pasan o llegan a su fin — 4 ocurrencias concentradas en el Apocalipsis. En Ap 9:12 «el primer ay pasó»; en Ap 11:14 «el segundo ay pasó»; en Ap 21:1 «el primer cielo y la primera tierra pasaron»; y en Ap 21:4 el llanto, el dolor y la muerte «pasaron». El español cambia a vocabulario temporal con ''pasar'', marcando la transición del movimiento espacial a la cesación cósmica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62741, 'spa', 'difundirse, extenderse', 'De noticias, fama o informes que salen o se difunden por una región — una sola ocurrencia en Mt 4:24, donde «la noticia de él se difundió [ἀπῆλθεν] por toda Siria». El español «salió» capta la idea de información que viaja como si fuera una persona que parte de un lugar y llega a muchos otros. Es una extensión metonímica natural del sentido 1: en lugar de una persona, es un informe el que «se va».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62746, 'spa', 'ir en pos de, seguir', 'Ir en pos de o perseguir — una sola ocurrencia en Jud 7, donde Sodoma y Gomorra, «habiendo ido en pos de [ἀπελθοῦσαι ὀπίσω] vicios contra naturaleza», sirven de ejemplo del juicio divino. El español «yendo» y el francés «étant allées» usan verbos de movimiento simples, pero la construcción ἀπέρχομαι ὀπίσω reconvierte paradójicamente el verbo de partida en verbo de búsqueda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62748, 'spa', 'Haber recibido en su totalidad, especialmente en sentido comercial o transaccion', 'Haber recibido en su totalidad, especialmente en sentido comercial o transaccional. En Mateo 6:2, 5, 16 Jesús declara que los hipócritas ἀπέχουσιν — ya han cobrado por completo su recompensa y nada más les queda por recibir. Filipenses 4:18 emplea la misma palabra cuando Pablo acusa recibo pleno del donativo de los filipenses. El español ''reciben'' y el alemán ''hat genug'' reflejan esta noción de transacción saldada y completa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62749, 'spa', 'Mantenerse apartado de algo, abstenerse — la voz media (ἀπέχεσθαι) usada para la', 'Mantenerse apartado de algo, abstenerse — la voz media (ἀπέχεσθαι) usada para la autocontención moral y dietética. La decisión histórica del Concilio de Jerusalén ordena a los creyentes gentiles ''abstenerse de'' alimentos contaminados e inmoralidad sexual (Hch 15:20, 29). Pablo la extiende a la pureza ética general en 1 Tesalonicenses 4:3 y 5:22. El español ''absteneos/abstenerse'' y sus paralelos en francés conservan la fuerza reflexiva del original.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62750, 'spa', 'Estar a distancia espacial o metafórica de un lugar o persona', 'Estar a distancia espacial o metafórica de un lugar o persona. En Mateo 14:24 la barca ἀπεῖχεν muchos estadios de tierra, mientras que en Mateo 15:8 (citando Is 29:13) ''su corazón está lejos (ἀπέχει) de mí''. El español distingue esto claramente con ''dista/distaba'', y el sentido se extiende desde la distancia geográfica medible (Lc 7:6; 15:20) hasta la dolorosa brecha espiritual entre el culto de labios y la devoción verdadera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62758, 'spa', 'Un uso impersonal que significa ''basta'' o ''el asunto está zanjado''', 'Un uso impersonal que significa ''basta'' o ''el asunto está zanjado''. Aparece únicamente en Marcos 14:41, donde Jesús en Getsemaní dice ἀπέχει tras encontrar a los discípulos dormidos una vez más. El matiz exacto se debate — ''¡basta!'' como resignación, o ''la cuenta está saldada'' enlazando con el sentido comercial — pero el español ''basta'' captura bien la brusca finalidad. Marca un punto de inflexión: la hora de la traición ha llegado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62762, 'spa', 'No creer / ser infiel', 'Rehusar creer o ser infiel, expresando incredulidad activa o desconfianza ante un mensaje, persona o realidad. Los discípulos ''no creyeron'' (ἠπίστησαν) el testimonio pascual de las mujeres (Mar 16:11; Luc 24:11), y algunos en Roma ''no creyeron'' la enseñanza de Pablo sobre Jesús (Hch 28:24). El español alterna entre ''incrédulos'' y ''no creyeron'', reflejando tanto la postura de resistencia como la negativa deliberada a aceptar la verdad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62769, 'spa', 'Incredulidad, falta de fe — Incredulidad o falta de fe como disposición arraigad', 'Incredulidad, falta de fe — Incredulidad o falta de fe como disposición arraigada que obstaculiza la actividad divina y pone en peligro la posición en el pacto. En los Evangelios Sinópticos, la incredulidad de Nazaret limita los milagros de Jesús (Mt 13:58; Mr 6:6), y la confesión angustiada de un padre — ''¡ayuda mi incredulidad!'' (Mr 9:24) — revela su lucha interior. Pablo la emplea teológicamente en Romanos 3:3, contrastando la infidelidad de Israel con la fidelidad de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62771, 'spa', 'Quien no cree, un incrédulo', 'Quien no cree, un incrédulo: el uso dominante en el Nuevo Testamento. Se aplica sustantivamente a los no cristianos (1 Co 6:6; 7:12-15; 14:22-24; 2 Co 6:14) y adjetivamente como reproche de Jesús a una ''generación incrédula'' (Mt 17:17; Mc 9:19). En Juan 20:27, el Cristo resucitado dice a Tomás ''no seas incrédulo sino creyente'' (μὴ γίνου ἄπιστος ἀλλὰ πιστός). En español, ''incrédulo'' traduce este sentido de manera consistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62774, 'spa', 'Infiel, desleal', 'Infiel, desleal: enfatizando el fracaso moral en el compromiso más que la ausencia intelectual de fe. En Lucas 12:46, al siervo malvado se le asigna parte con los ''infieles'' (ἀπίστων), y Apocalipsis 21:8 enumera a los ἄπιστοι junto con asesinos y mentirosos en el lago de fuego. La connotación pasa de ''aún no creyente'' a ''haber quebrantado la fe,'' más cercana al sentido clásico griego de deslealtad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62779, 'spa', 'Increíble, difícil de creer', 'Increíble, difícil de creer: el sentido adjetival pasivo aplicado a proposiciones, no a personas. En Hechos 26:8, Pablo pregunta a Agripa: ''¿Por qué se juzga increíble (ἄπιστον) entre vosotros que Dios resucite a los muertos?'' En español, ''increíble'' captura perfectamente este sentido, mostrando el alcance clásico de la palabra donde el alfa privativa niega la credibilidad de una afirmación en lugar de la fe de una persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62782, 'spa', 'Generosidad / liberalidad', 'Generosidad, liberalidad: dar con corazón abierto que brota de la integridad de propósito, sin motivos ocultos ni cálculos interesados. La aflicción de los macedonios produjo ''riquezas de generosidad'' (2 Cor 8:2), y Dios enriquece a los creyentes ''para toda generosidad'' (2 Cor 9:11). Pablo elogia el dar hecho ἐν ἁπλότητι (Rom 12:8), es decir, sin agenda oculta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62783, 'spa', 'Sinceridad / sencillez', 'Sinceridad, sencillez de devoción: lealtad indivisa y transparencia de propósito, sin astucia ni doblez de ánimo. Pablo teme que los corintios sean desviados de su ''sinceridad hacia Cristo'' (2 Cor 11:3), y los siervos deben obedecer ''en sencillez de corazón'' (Ef 6:5; Col 3:22). En 2 Cor 1:12, Pablo defiende su conducta como marcada por ''santidad y sinceridad de Dios'', contrastando con la astucia de la serpiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62787, 'spa', 'Ojo claro y sano', 'En ambas ocurrencias evangélicas (Mateo 6:22, Lucas 11:34), esto describe el ojo ''claro'' o ''sano'' en la enseñanza de Jesús sobre tesoros y luz. El contexto lo contrasta con el ''ojo malo'' (un modismo semítico para la tacañería), por lo que las traducciones multilingües que apuntan a cualidades morales como ''sano'' y ''sencillo'' (simple, generoso) están bien fundadas. La metáfora del ojo representa devoción incondicional a Dios, no dividida entre el servicio a Dios y las riquezas. Un ojo claro permite que todo el cuerpo esté lleno de luz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62789, 'spa', 'separación u origen', 'Sentido básico espacial y temporal: movimiento o distancia desde un punto de partida. ''Salir de Jerusalén'', ''desde el principio'', ''lejos de casa''. Incluye la idea de procedencia geográfica, origen étnico o fuente de información.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62792, 'spa', 'causal o agentivo', 'Extensión del sentido de origen al ámbito de la causación: ''por causa de'', ''debido a'', ''como resultado de''. En voz pasiva puede introducir al agente indirecto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62793, 'spa', 'partitivo', 'Uso partitivo que indica la totalidad de la cual se toma una parte: ''algunos de vosotros'', ''uno de los doce''. Se solapa con el sentido de origen, pero enfatiza la relación todo-parte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62794, 'spa', 'Desembarcar, bajar', 'Descender, desembarcar, salir a tierra: el acto físico de abandonar una embarcación. En Luke 5:2 se describe a los pescadores que habían bajado de sus barcas para lavar las redes; John 21:9 narra a los discípulos desembarcando y encontrando unas brasas encendidas. El castellano ''desembarcaron'' apunta directamente a este significado concreto y náutico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62795, 'spa', 'Arrojar o desechar', 'Marcos 10:50 muestra la acción física dramática: el ciego Bartimeo ''arroja'' su manto exterior mientras salta para encontrarse con Jesús, la urgencia y el gozo evidentes en el gesto. Hebreos 10:35 cambia a lo metafórico: se insta a los creyentes a no ''desechar'' su confianza (valentía, libertad de hablar ante Dios), que tiene gran recompensa. Las traducciones interlingüísticas se unen alrededor de este núcleo de descartar con determinación, ya sea la vestidura que obstaculiza el movimiento o la valentía que sostiene la fe bajo presión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62798, 'spa', 'Pérdida o rechazo', 'Hechos 27:22 contiene la garantía de Pablo a la tripulación azotada por la tormenta: no habrá ''pérdida'' de vida (ἀποβολή), aunque el barco será destruido, un significado concreto y físico. Romanos 11:15 cambia completamente a la teología: si el ''rechazo'' (o ''desechamiento'') de Israel significa reconciliación para el mundo, ¿qué significará su aceptación sino vida de entre los muertos? Aquí el término soporta el peso del misterio divino: Dios usa incluso el rechazo temporal de su pueblo para bendecir a las naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62800, 'spa', 'censo imperial romano', 'Lucas 2:2 prepara el escenario del nacimiento de Jesús: ''este registro (ἀπογραφή) fue el primero cuando Quirinio era gobernador de Siria''—un anclaje cronológico que ha generado mucha discusión histórica. Hechos 5:37 se refiere al mismo período censal, cuando ''Judas el Galileo se levantó en los días del registro'' liderando una revuelta. Ambos pasajes usan el término precisamente para el censo imperial romano, no una lista genealógica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62801, 'spa', 'Empadronarse, inscribirse', 'Registrarse o inscribirse en un censo oficial o lista tributaria por mandato de una autoridad gobernante. La voz media predomina en el NT, subrayando el cumplimiento voluntario del decreto imperial. Las cuatro apariciones lucanas (Luke 2:1, 3, 5) se refieren al censo bajo Augusto. El castellano ''empadronado'' apunta uniformemente al registro cívico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62802, 'spa', 'Exhibir, demostrar', 'Mostrar públicamente, demostrar o exhibir, ya sea mediante atestación milagrosa o autopresentación deliberada. En Acts 2:22, Dios demostró a Jesús ante Israel con señales y prodigios. En 1 Corinthians 4:9, Pablo lo usa para describir a Dios poniendo a los apóstoles en exhibición como condenados en una arena. El término abarca desde la acreditación divina hasta la ostentación blasfema.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62804, 'spa', 'Diezmar o recaudar diezmos', 'Dar o recaudar la décima parte de los bienes o productos como obligación religiosa. El verbo opera en dos direcciones en el NT: la recaudación activa por parte de los sacerdotes (Heb 7:5, donde los levitas diezman al pueblo) y el pago personal de diezmos (Luke 18:12). La aguda crítica de Jesús en Matthew 23:23 y Luke 11:42 apunta a quienes diezman hierbas del huerto con esmero meticuloso pero descuidan los asuntos de mayor peso de la ley.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62805, 'spa', 'aceptable ante Dios', 'El lema describe lo que es aceptable o agradable, especialmente a Dios. Ambas ocurrencias en 1 Timoteo enfatizan la aprobación divina: la oración por todas las personas es ''aceptable a Dios nuestro Salvador'' (2:3), y cuidar de la familia es ''aceptable delante de Dios'' (5:4). La evidencia multilingüe (español aceptable, alemán angenehm ''placentero/agradable'') confirma el rango semántico central de cumplir un estándar de aceptabilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62806, 'spa', 'Aceptar (un mensaje)', 'Aceptar o recibir un mensaje, enseñanza o informe con aprobación intelectual o gratitud. Las dos ocurrencias marcan momentos decisivos de respuesta: en Pentecostés, «los que recibieron su palabra fueron bautizados» (Hch 2:41), donde ἀποδεξάμενοι señala aceptación plena del kerigma de Pedro; y en Hch 24:3, Tértulo usa ἀποδεχόμεθα («reconocemos con gratitud») en su aduladora apertura ante Félix.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62807, 'spa', 'Acoger, recibir (persona)', 'Recibir o acoger a una persona con alegría, hospitalidad o disposición favorable: el acto relacional y físico de dar la bienvenida. Este sentido dominante (5 ocurrencias) abarca desde la multitud que «recibió» a Jesús en Capernaúm (Lc 8:40) hasta Pablo «recibiendo a todos los que venían a él» en su alojamiento romano (Hch 28:30). El español «recibir», el francés «accueillir» y el alemán «empfangen» captan esta hospitalidad personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62813, 'spa', 'Partir de viaje', 'Partir de viaje a un lugar distante, viajar al extranjero o irse a una tierra lejana. El compuesto ἀπο-δημέω (lejos + pueblo/patria) implica dejar la propia comunidad por un período prolongado. En el NT funciona como recurso narrativo en las parábolas de Jesús: el dueño de la viña que planta, arrienda y «se fue» (Mt 21:33; Mr 12:1), el señor que confía talentos antes de partir (Mt 25:14-15) y el hijo pródigo que se marcha a un país lejano (Lc 15:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62818, 'spa', 'retribuir, recompensar', 'Recompensar, retribuir o dar a alguien lo que se le debe — ya sea retribución divina, salario por labor, honra, tributos o votos. Es el sentido de mayor peso teológico, destacado en la enseñanza de Jesús sobre el Padre que «te recompensará» por los actos ocultos de piedad (Mt 6:4, 6, 18) y en la promesa escatológica de que el Hijo del Hombre «pagará a cada uno conforme a sus obras» (Mt 16:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62819, 'spa', 'devolver, restituir', 'Devolver, restituir o retornar algo a su legítimo dueño o estado original. En Mt 22:21 / Mr 12:17 Jesús dice «Dad al César lo que es del César» — no simplemente «dad» sino «devolved lo que ya le pertenece». Lc 4:20 lo usa cuando Jesús «devuelve» el rollo al ministro de la sinagoga, y Lc 9:42 cuando Jesús «devuelve» al muchacho sanado a su padre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62821, 'spa', 'pagar, saldar deuda', 'Pagar o devolver una deuda financiera, saldando una obligación monetaria. Concentrado en la parábola del siervo malvado (Mt 18:25-34), donde el verbo aparece repetidamente en el ruego desesperado «todo te lo pagaré». En Mt 5:26 Jesús advierte que el deudor no saldrá hasta que pague el último cuadrante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62828, 'spa', 'dar, rendir cuenta', 'Dar, entregar o rendir algo requerido — una cuenta, testimonio o informe — a una autoridad o audiencia. En Mt 12:36 los hombres «darán cuenta» de toda palabra ociosa; en Lc 16:2 el mayordomo debe «rendir» cuenta de su administración; en Hch 4:33 los apóstoles «daban» testimonio de la resurrección con gran poder.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62832, 'spa', 'producir, dar fruto', 'Producir fruto, cosecha o resultados — una extensión metafórica donde el «devolver» es la producción de la naturaleza o del esfuerzo. En Ap 22:2 el árbol de la vida «produce» su fruto cada mes, y en He 12:11 la disciplina «produce» fruto apacible de justicia. Este sentido preserva la noción raíz de entregar lo que se espera, ahora en clave agrícola.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62841, 'spa', 'vender', 'Vender, entregar en una transacción comercial a cambio de dinero. En Hch 5:8 Pedro pregunta a Safira si la heredad fue «vendida» por cierto precio; en Hch 7:9 los patriarcas «vendieron» a José a Egipto; en He 12:16 Esaú «vendió» su primogenitura por una sola comida. El contexto comercial distingue claramente este sentido de «devolver».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62854, 'spa', 'Rechazar tras examen', 'Rechazar a alguien o algo después de examinarlo, probarlo o deliberar, declarándolo no apto o indigno y descartándolo. El término conlleva escrutinio profesional: constructores que inspeccionan piedras y descartan la inadecuada (Sal 118:22, citado en Mat 21:42; Mar 12:10; Luc 20:17; 1 Ped 2:4, 7). Jesús lo usa para referirse al rechazo de los líderes religiosos hacia él como Mesías (Mar 8:31; Luc 9:22; 17:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62858, 'spa', 'aceptación plena', 'El sustantivo significa aceptación o aprobación, particularmente de una declaración o enseñanza como confiable. En ambos pasajes de Timoteo, Pablo une ἀποδοχή con ''digno'' (ἄξιος) para enfatizar que ciertos dichos merecen aceptación completa—no mero asentimiento intelectual sino abrazo de todo corazón. La construcción genitiva (''digno de toda aceptación'') muestra que esto es más que recepción pasiva; es aprobación activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62859, 'spa', 'despojamiento físico-espiritual', 'El sustantivo describe quitarse o remover, típicamente algo que se lleva puesto o habita. Primera Pedro 3:21 lo usa negativamente: el bautismo no es meramente ''quitar suciedad corporal'' (ἀπόθεσις ῥύπου σαρκός) sino apelación pactual a Dios—el acto físico de lavar no es el punto. Segunda Pedro 1:14 pasa a metáfora: ''el despojamiento de mi tienda'' usa el sustantivo para la muerte próxima de Pedro, viendo el cuerpo como morada temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62860, 'spa', 'Granero, depósito, troje', 'Estructura para almacenar grano cosechado: un granero, troje o depósito. En cada aparición neotestamentaria la imagen sirve a un propósito teológico: el cuidado divino que supera la necesidad de graneros (Mt 6:26), la recolección escatológica del trigo (Mt 3:12; Lc 3:17) y la insensatez de acumular bienes terrenales (Lc 12:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62865, 'spa', 'morir físicamente', 'Muerte física: el cese de la vida corporal, ya sea natural, violenta o judicial. Abarca desde escenas narrativas de muerte (Mt 8:32, los cerdos; Mc 9:26, una muerte aparente) hasta declaraciones solemnes sobre el martirio (Mt 26:35, ''aunque tenga que morir contigo''). Se traduce uniformemente en todas las lenguas (spa: murió, fra: mourir, deu: sterben), confirmando su carácter de sentido predeterminado y no marcado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62877, 'spa', 'morir figurada/espiritualmente', 'Muerte figurada o espiritual: morir al pecado, a la ley o al viejo ser, especialmente en la teología paulina. Romanos 6:2 pregunta ''¿cómo viviremos aún en el pecado, los que hemos muerto a él?'', mientras que Romanos 6:8 proclama ''si morimos con Cristo, creemos que también viviremos con él''. Las formas de traducción idénticas entre lenguas (spa: morimos/morí, deu: sterben) muestran que Pablo se apoya en el verbo literal para comunicar una realidad transformadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62896, 'spa', 'Restaurar al estado previo', 'Restaurar algo o a alguien a una condición previa y apropiada, ya sea sanidad física o restablecimiento escatológico. Los milagros de sanidad muestran restauración corporal instantánea: una mano ''fue restaurada'' sana como la otra (Mar 3:5), y la vista ''fue restaurada'' para que el hombre viera todo con claridad (Mar 8:25). El uso profético-escatológico contempla la restauración cósmica: Elías ''restaura todas las cosas'' (Mat 17:11; Mar 9:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62902, 'spa', 'Ser revelado, descubierto o sacado a la luz (pasivo/pasivo divino), referido a v', 'Ser revelado, descubierto o sacado a la luz (pasivo/pasivo divino), referido a verdades ocultas, realidades escatológicas, ira divina o gloria que se manifiestan. A menudo un ''pasivo teológico'' donde Dios es el agente implícito. Nada cubierto quedará oculto (Mt 10:26; Lc 12:2), la gloria del Señor será revelada (Ro 8:18), y el hombre de iniquidad será revelado en los últimos días (2 Ts 2:3, 6, 8). En español, ''ser revelado'' y ''es revelado'' marcan este sentido pasivo con claridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62907, 'spa', 'Revelar o dar a conocer activamente algo que antes estaba oculto, con Dios o el ', 'Revelar o dar a conocer activamente algo que antes estaba oculto, con Dios o el Espíritu como sujeto explícito que comunica verdades divinas a receptores escogidos. Jesús alaba al Padre por revelar a los pequeños lo que estaba oculto a los sabios (Mt 11:25; Lc 10:21), la confesión de Pedro viene por revelación divina (Mt 16:17), y el Espíritu revela las cosas profundas de Dios (1 Co 2:10). En español, ''revelaste'' y ''reveló'' marcan la agencia activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62914, 'spa', 'El acto o evento de revelación divina — el descubrimiento de lo que estaba previ', 'El acto o evento de revelación divina — el descubrimiento de lo que estaba previamente oculto, ya sea una verdad espiritual específica, la identidad de una persona o realidades escatológicas. Pablo lo emplea para el misterio del evangelio ahora revelado (Ro 16:25; Ef 3:3), para la manifestación futura de Cristo y de los creyentes (Ro 8:19; 1 Co 1:7; 2 Ts 1:7), y para la visión profética otorgada en el culto (1 Co 14:6, 26). Simeón llama al niño Jesús ''luz para revelación a las naciones'' (Lc 2:32), y el término da título al último libro de las Escrituras. El español ''revelación'' conserva fielmente el sentido de hacer manifiesto lo que estaba escondido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62919, 'spa', 'expectativa anhelante intensa', 'El sustantivo denota expectativa o anhelo intenso y ansioso, con imaginería física vívida integrada en su etimología (ἀπό ''desde'' + κάρα ''cabeza'' + δοκέω ''observar''). Romanos 8:19 personifica a la creación misma como comprometida en ἀποκαραδοκία, ''esperando ansiosamente la revelación de los hijos de Dios''—todo el cosmos pictorizado como estirando su cuello hacia la redención. Filipenses 1:20 lo aplica a la esperanza personal de Pablo: su expectativa ansiosa de que Cristo sea magnificado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62920, 'spa', 'Reconciliacion en Cristo', 'Describe exclusivamente la obra reconciliadora de Cristo en las epistolas paulinas de la cautividad. Efesios 2:16 declara el proposito de Cristo de «reconciliar» (ἀποκαταλλάξῃ) a ambos grupos con Dios mediante la cruz, aboliendo la enemistad. Colosenses 1:20 anuncia la intencion divina de «reconciliar» (ἀποκαταλλάξαι) todas las cosas, con alcance cosmico. Colosenses 1:22 lo personaliza: Cristo «os ha reconciliado» (ἀποκατήλλαξεν) mediante su muerte corporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62922, 'spa', 'Reservado o destinado', 'Estar guardado, reservado o destinado para un propósito futuro o un desenlace señalado por Dios. En Luke 19:20, el siervo mantuvo su mina «guardada» en un paño — simple almacenamiento físico. Colossians 1:5 y 2 Timothy 4:8 elevan la imagen a la esperanza escatológica y la recompensa «reservada» en los cielos. Hebrews 9:27 cambia al decreto divino: está «establecido» para los hombres morir una sola vez.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62923, 'spa', 'Decapitar', 'Ejecutar mediante decapitación, cortando la cabeza. Cada uso en el NT se refiere a la ejecución de Juan el Bautista por Herodes Antipas: el acto mismo (Matt 14:10; Mark 6:27) y la confesión retrospectiva y atormentada de Herodes (Mark 6:16; Luke 9:9). Las formas en aoristo subrayan el carácter consumado e irreversible de la acción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62925, 'spa', 'Cortar, cercenar', 'Cortar o separar físicamente con un instrumento cortante. Abarca la mayoría de apariciones: la oreja del siervo del sumo sacerdote (Jn 18:10, 18:26), la hipérbole de Jesús sobre amputar la mano o el pie que hace pecar (Mr 9:43, 45) y el corte de las cuerdas del bote (Hch 27:32).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62928, 'spa', 'Mutilarse, castrarse', 'Uso reflexivo en voz media: mutilarse o castrarse a sí mismo. Aparece únicamente en Gálatas 5:12, donde Pablo desea con sarcasmo que los judaizantes se ''corten del todo''. La voz media señala acción autodirigida, y el español ''se mutilaran'' preserva esa fuerza reflexiva. Los lectores antiguos captarían la alusión a la autocastración de ciertos cultos paganos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62930, 'spa', 'responder verbalmente', 'Dar una réplica o respuesta verbal a una pregunta, declaración o situación, empleado frecuentemente como fórmula narrativa participial (ἀποκριθείς, ''habiendo respondido'') para introducir discurso directo en los Evangelios. Sigue un patrón hebraizante donde responder no requiere pregunta previa, sino que marca el inicio del habla en un contexto dialógico (Mt 3:15; 11:25). Español respondiendo y alemán antwortet convergen en este sentido único y dominante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62944, 'spa', 'Respuesta verbal', 'Una contestación o réplica verbal dada en respuesta a una pregunta, desafío o indagación. En Luke 2:47, el Jesús de doce años asombra a los maestros del templo con la calidad de sus respuestas. Luke 20:26 describe a los adversarios silenciados por la hábil respuesta de Jesús ante la trampa del tributo. John 1:22 registra a los sacerdotes exigiendo una respuesta definitiva de Juan el Bautista sobre su identidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62945, 'spa', 'Esconder u ocultar', 'Esconder, ocultar o mantener en secreto, especialmente verdades divinas encubiertas por el propósito deliberado de Dios hasta el tiempo señalado de revelación. En Luke 10:21, Jesús da gracias al Padre por haber escondido estas cosas de los sabios. Los tres usos paulinos (1 Cor 2:7; Eph 3:9; Col 1:26) emplean participios perfectos pasivos para describir la sabiduría o el misterio de Dios oculto desde los siglos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62946, 'spa', 'Oculto para revelación', 'Describe aquello que está actualmente escondido pero destinado a ser revelado. Marcos 4:22 y Lucas 8:17 emplean una formulación idéntica: nada hay «oculto» (ἀπόκρυφον) sino para ser manifestado. Colosenses 2:3 habla de tesoros escondidos: en Cristo «están ocultos» (ἀπόκρυφοι) todos los tesoros de sabiduría y conocimiento. La paradoja de que el ocultamiento sirve a una revelación final recorre todos estos textos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62947, 'spa', 'matar, dar muerte', 'Causar la muerte de una persona o animal por acción violenta, judicial u hostil — el sentido activo de matar o ejecutar. Este sentido dominante (60 ocurrencias) abarca el asesinato, la ejecución y la violencia profética. Pasajes clave incluyen la enseñanza de Jesús sobre el testimonio intrépido (Mt 10:28), la parábola de los labradores malvados que matan al hijo del dueño (Mt 21:38-39) y la violencia contra los profetas (Mt 23:37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62952, 'spa', 'ser muerto, padecer muerte', 'Padecer la muerte a manos de otro — la experiencia pasiva de ser asesinado, ejecutado o martirizado. A lo largo de 14 ocurrencias, las formas pasivas revisten una profunda significación cristológica y martirológica. La triple predicción de la Pasión en los Sinópticos emplea esta forma: «el Hijo del Hombre debe ser muerto» (Mr 8:31; 9:31; Lc 9:22), y Apocalipsis describe a los fieles «muertos por causa de la palabra de Dios» (Ap 6:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62977, 'spa', 'Engendrar, dar a luz', 'Usado metafóricamente en Santiago 1:15 donde el pecado ''engendra'' la muerte, y literalmente en 1:18 donde Dios ''dio a luz'' a los creyentes mediante la palabra. Las formas griegas media/pasiva sugieren tanto el acto activo de dar a luz como el de ser nacido, reflejando el proceso biológico dual. Las glosas multilingües emplean uniformemente terminología de nacimiento y generación, confirmando el campo semántico fisiológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62978, 'spa', 'Rodar una piedra', 'Hacer rodar o quitar rodando un objeto pesado; en el NT se usa exclusivamente para remover la piedra del sepulcro de Jesús. El ángel la rodó (Mat 28:2), las mujeres preguntaban quién la rodaría (Mar 16:3), y la hallaron ya rodada (Mar 16:4; Luc 24:2). Las formas pasivas perfectas recalcan la acción consumada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62979, 'spa', 'Recibir, obtener — Recibir u obtener algo — una recompensa, promesa o recompensa', 'Recibir, obtener — Recibir u obtener algo — una recompensa, promesa o recompensa — sin implicar posesión previa. Se usa ampliamente para recibir salarios, bendiciones o consecuencias. En Lucas 16:25, Abraham le recuerda al rico que recibió sus bienes; en Gálatas 4:5, los creyentes reciben la adopción como hijos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62980, 'spa', 'Llevar aparte, tomar consigo — Llevar a alguien aparte físicamente, implicando i', 'Llevar aparte, tomar consigo — Llevar a alguien aparte físicamente, implicando iniciativa activa en lugar de recepción pasiva. En Marcos 7:33, Jesús ''tomó aparte'' al sordo de la multitud antes de sanarlo. Solo hay una ocurrencia en el NT, pero el desplazamiento semántico de recibir a tomar activamente es significativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62987, 'spa', 'Recibir de vuelta, recuperar — Recibir de vuelta o recuperar algo o alguien que ', 'Recibir de vuelta, recuperar — Recibir de vuelta o recuperar algo o alguien que se poseía anteriormente, que se perdió o se prestó, enfatizando la restauración. En la parábola del Hijo Pródigo (Lc 15:27), el padre ''recibió de vuelta'' a su hijo con vida, y en Lucas 6:34, los prestamistas esperan ''recibir de vuelta'' la misma cantidad. El prefijo griego ἀπο- combinado con el contexto de pérdida previa marca la recuperación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62989, 'spa', 'Disfrute, goce', 'Aparece en contextos que contrastan placeres terrenales (1 Tim 6:17 - disfrute legítimo de los dones de Dios; Heb 11:25 - placer temporal del pecado). El término no lleva juicio moral inherente; el contexto determina si el disfrute es apropiado o inapropiado. El griego clásico lo usa para ventaja o fruto obtenido de algo, lo cual concuerda con el énfasis paulino en la provisión divina generosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62990, 'spa', 'Permanecer, quedar', 'Permanecer o quedar en voz media-pasiva intransitiva, donde el sujeto es lo que persiste. Hebreos usa este sentido tres veces: ''queda para algunos entrar'' en el reposo de Dios (Heb 4:6), ''queda un reposo sabático'' para su pueblo (Heb 4:9) y ''ya no queda sacrificio'' para quienes pecan voluntariamente (Heb 10:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62991, 'spa', 'Dejar atrás, abandonar', 'Dejar atrás o abandonar en voz activa transitiva. Pablo ''dejó'' (ἀπέλιπον) su capa con Carpo en Troas (2 Ti 4:13), ''dejó'' enfermo a Trófimo en Mileto (2 Ti 4:20) y dejó a Tito en Creta con una misión específica (Tit 1:5). Los ángeles que ''abandonaron'' su morada propia (Jud 1:6) representan el caso más dramático.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62994, 'spa', 'perder, no conservar', 'Perder algo o a alguien que se posee o de quien se es responsable. El pastor pierde una oveja de cien (Lc 15:4); una mujer pierde una moneda de diez (Lc 15:8); quien quiera salvar su vida la perderá (Mt 10:39; 16:25). El español «perder» expresa el dolor de lo que se estimaba. Este sentido carece de la violencia de la destrucción: la pérdida puede ser accidental o por negligencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62995, 'spa', 'destruir, arruinar', 'Sentido activo transitivo: destruir, matar, llevar a la ruina total. Herodes procura destruir al niño (Mt 2:13); los fariseos conspiran para destruir a Jesús (Mt 12:14); el rey envía ejércitos para destruir a los homicidas (Mt 22:7). El español «destruir» conserva la raíz latina destruere, subrayando la violencia causativa de este uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62997, 'spa', 'perecer, ser destruido', 'Sentido intransitivo en voz media: perecer, ser destruido, llegar a la ruina o la muerte. Se emplea para personas en peligro mortal («¡Señor, sálvanos, que perecemos!», Mt 8:25), odres viejos que revientan y se echan a perder (Mt 9:17), y la advertencia escatológica de que «ancho es el camino que lleva a la perdición» (Mt 7:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63007, 'spa', 'perdido (estado)', 'Participio perfecto pasivo usado como adjetivo: «perdido», describiendo el estado de estar extraviado, alejado o espiritualmente errante. Jesús es enviado a «las ovejas perdidas de la casa de Israel» (Mt 10:6; 15:24); las parábolas de Lucas 15 giran en torno a lo que estaba perdido (τὸ ἀπολωλός) y es hallado. El español «perdido/perdida» funciona como equivalente exacto, empleado sustantivamente igual que el participio griego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63043, 'spa', 'Apolos (nombre propio, persona) — El cristiano judío alejandrino, instruido en l', 'Apolos (nombre propio, persona) — El cristiano judío alejandrino, instruido en las Escrituras, que recibió enseñanza más completa de Priscila y Aquila (Hch 18:24-28) y se convirtió en un predicador importante en la iglesia de Corinto. Pablo aborda el faccionalismo que generó su popularidad (1 Co 1:12; 3:4-6, 22; 4:6), presentándose a sí mismo y a Apolos como colaboradores en el campo de Dios. Mencionado también en 1 Corintios 16:12 y Tito 3:13.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63047, 'spa', 'Hacer una defensa, defenderse — Ofrecer una defensa o apología verbal contra acu', 'Hacer una defensa, defenderse — Ofrecer una defensa o apología verbal contra acusaciones, principalmente en contextos forenses ante magistrados, gobernadores o tribunales. Jesús prepara a sus discípulos para este escenario (Lc 12:11; 21:14). Los discursos apologéticos de Pablo en Hechos ejemplifican el término: ante la multitud en Jerusalén (Hch 22:1, implícito), Félix (Hch 24:10), y Festo y Agripa (Hch 25:8; 26:1-2, 24). Pablo también lamenta que nadie le acompañó en su primera defensa (2 Ti 4:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63056, 'spa', 'Defensa verbal', 'Defensa verbal razonada o justificacion presentada en respuesta a una acusacion, critica o interrogatorio. Pablo la utiliza en contextos legales formales: su defensa ante la multitud en Jerusalen (Hch 22:1) y su derecho a defenderse ante sus acusadores (Hch 25:16). Tambien aparece en contextos teologicos: la defensa y confirmacion del evangelio (Fil 1:7), y la disposicion para dar razon de la esperanza que se profesa (1 Pe 3:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63060, 'spa', 'Limpieza espiritual bautismal', 'Ambas apariciones conectan el bautismo en agua con la limpieza espiritual (Hch 22:16; 1 Cor 6:11). La voz media griega en ambos pasajes sugiere agencia personal en recibir la limpieza más que recepción puramente pasiva. La evidencia multilingüe muestra terminología directa de lavado en todos los idiomas, aunque el alemán preserva las formas griegas, sugiriendo reconocimiento de esto como vocabulario técnico bautismal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63061, 'spa', 'Redención, liberación (liberación mediante rescate)', 'Redención, liberación (liberación mediante rescate). Liberación efectuada mediante el pago de un rescate, usada teológicamente respecto a la obra expiatoria de Cristo que asegura el perdón de los pecados (Ro 3:24; Ef 1:7; Col 1:14; Heb 9:15) y de la redención escatológica que los creyentes esperan en el retorno de Cristo (Lc 21:28; Ro 8:23; Ef 1:14; 4:30). La metáfora subyacente de compra mediante rescate permea todas las ocurrencias, ya sea aplicada a la liberación espiritual presente o a la consumación futura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63065, 'spa', 'repudiar, divorciarse', 'Divorciarse o repudiar al cónyuge: 15 ocurrencias en los pasajes sinópticos sobre el matrimonio (Mt 1:19; 5:31-32; 19:3-9; Mr 10:2-12; Lc 16:18). El árabe emplea la raíz dedicada al divorcio ṭ-l-q en Forma II, el coreano cambia al vocabulario de abandono, y el suajili selecciona lenguaje de separación conyugal. El trasfondo halájico Hilel/Shamai de Mt 19 confirma la especificidad de este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63066, 'spa', 'soltar, liberar', 'Soltar o poner en libertad de custodia, cautiverio u obligación: 32 ocurrencias concentradas en los relatos de la Pasión en torno a la costumbre pascual de liberar a un preso (Mt 27:15-26; Mr 15:6-15; Jn 18:39). También abarca la liberación de una enfermedad (Lc 13:12, la mujer atada por Satanás). El español «soltar» y «liberar» se corresponden con precisión a este marco de liberación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63070, 'spa', 'despedir, enviar', 'Despedir o enviar lejos a un grupo o individuo: 18 ocurrencias, prominentes en los relatos de alimentación donde Jesús se niega a «despedir» a las multitudes hambrientas (Mt 14:15, 22-23; 15:23, 32). La evidencia crucial para separar este sentido del primero es que el árabe emplea una raíz completamente distinta (ṣarafa, «despedir»), y el coreano distingue «enviar» del vocabulario de liberación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63085, 'spa', 'perdonar, absolver', 'Perdonar o absolver: dos ocurrencias en Lucas 6:37 («perdonad y seréis perdonados»). La metáfora de «desatar» se extiende de ataduras físicas a deudas morales. El árabe emplea la raíz enteramente distinta gh-f-r (ighfirū), el suajili usa -samehe («perdonar»), el coreano 용서하다: todo vocabulario dedicado al perdón, sin solapamiento con liberación, despido o divorcio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63095, 'spa', 'partir, retirarse', 'Partir o despedirse: una sola ocurrencia en Hechos 28:25, donde los dirigentes judíos en Roma «se iban» tras la discusión con Pablo. El español «se iban» trata este uso como una partida intransitiva en voz media, no como ser liberado por otro. Bien atestiguado en el griego clásico, pero marginal en el Nuevo Testamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63112, 'spa', 'Desviación espiritual', 'Usado exclusivamente en contextos de desviación espiritual o teológica (Mc 13:22 - engaño por falsos profetas; 1 Tim 6:10 - desviarse de la fe). Las formas pasivas en ambos pasajes indican ser desviado por fuerzas externas (señales engañosas, avaricia). El español ''engañar'' enfatiza el aspecto del engaño, mientras el alemán ''abirren'' captura la noción de desviarse del curso, ambas dimensiones válidas del griego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63113, 'spa', 'Zarpar, navegar', 'Zarpar o partir por barco, marcando la transición marítima entre lugares. Sus cuatro apariciones neotestamentarias están en Hechos: Bernabé y Saulo zarpan de Seleucia hacia Chipre (Hch 13:4), navegan de Atalia a Antioquía (Hch 14:26), Pablo pasa junto a Mileto (Hch 20:15) y comienza el viaje prisionero rumbo a Roma (Hch 27:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63114, 'spa', 'Ahogar, asfixiar', 'Aparece solo en Lucas 8 en dos contextos distintos pero relacionados: plantas siendo ahogadas por espinas (v.7) y cerdos ahogándose en agua (v.33). Ambos involucran muerte por restricción de aire. La metáfora agrícola depende de la familiaridad de los oyentes con espinas literalmente estrangulando cultivos. Las glosas multilingües distinguen entre ahogar (espinas) y anegarse (cerdos), mostrando que los traductores reconocieron los contextos diferentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63115, 'spa', 'Estar perplejo, desconcertado', 'Hallarse mentalmente sin salida, perplejo o desconcertado, incapaz de determinar el curso de acción correcto. No implica simple desconocimiento sino una lucha activa ante una situación que resiste toda solución fácil. Pasajes clave: Mr 6:20 (Herodes perplejo), Lc 24:4 (las mujeres ante la tumba), Jn 13:22 (los discípulos desconcertados) y 2 Co 4:8 (perplejidad sin desesperación).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63126, 'spa', 'Arrancar, separar forzosamente', 'Arrancar, apartar violentamente o separar a la fuerza en sentido físico, espacial o relacional. Pedro saca su espada en Getsemaní (Mat 26:51). Jesús «se apartó» a un tiro de piedra para orar (Luc 22:41). Falsos maestros «arrastrarán» discípulos tras de sí (Hch 20:30). En Mileto los creyentes se «arrancaron» unos de otros en dolorosa despedida (Hch 21:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63127, 'spa', 'Apostasía religiosa', 'Ambas ocurrencias llevan grave peso teológico: abandonar el pacto (Hechos 21:21) o rebelión escatológica (2 Tes 2:3). El artículo definido en 2 Tesalonicenses (''la apostasía'') sugiere una revuelta específica y reconocible del fin de los tiempos. Notablemente, los cuatro idiomas destino simplemente transliteran el término griego en lugar de traducirlo, indicando que ''apostasía'' se ha convertido en un término técnico fijo en el cristianismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63128, 'spa', 'Carta de divorcio', 'Aparece exclusivamente en la enseñanza de Jesús sobre el divorcio, en referencia a la disposición mosaica. Mateo 5:31 menciona el requisito de entregar una «carta de divorcio» (ἀποστασίου). Mateo 19:7 y Marcos 10:4 recogen la pregunta de los fariseos sobre por qué Moisés mandó dar «carta de divorcio» (ἀποστασίου). Jesús responde que esto fue permitido por la dureza de corazón, pero no era el designio original de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63130, 'spa', 'enviar en misión', 'El sentido activo dominante: enviar a alguien con una misión o encargo específico bajo la autoridad del que envía. Representa 112 de 133 apariciones y es el núcleo del que deriva el sustantivo ἀπόστολος. Jesús envía a los Doce (Mt 10:5), los propietarios envían siervos a cobrar de los labradores (Mt 21:34), y Dios envía profetas y ángeles. El español envió, el alemán sendet y el francés envoyer convergen en este sentido de despacho autorizado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63135, 'spa', 'ser enviado / comisionado', 'Voz pasiva o pasiva divina: ser enviado, ser comisionado como emisario. Con 19 apariciones, esta forma suele portar profundo peso teológico: Jesús declara ''fui enviado'' a las ovejas perdidas de Israel (Mt 15:24), y el ángel Gabriel anuncia ''fui enviado'' para hablar a Zacarías (Lc 1:19). El español enviado y el alemán gesandt reflejan el comisionamiento pasivo con clara connotación de autoridad delegada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63154, 'spa', 'despedir, echar fuera', 'Enviar fuera o despedir de la propia presencia, con énfasis en la partida más que en la misión. Solo 2 apariciones claras: los demonios ruegan a Jesús que no los ''envíe fuera'' de la región (Mc 5:10), y los labradores ''despiden'' al siervo con las manos vacías (Mc 12:3). Este sentido preserva el griego clásico más antiguo de ἀπο-στέλλω como ''alejar'', más cercano al destierro que al comisionamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63162, 'spa', 'Defraudar, privar, robar', 'Defraudar, privar o robar a alguien algo que legítimamente le corresponde, ya sean bienes, salarios o derechos conyugales. El sentido activo enfatiza la retención injusta (Mr 10:19; 1 Co 6:8), mientras las formas pasivas describen la experiencia de ser estafado (1 Co 6:7). Pablo extiende el concepto al ámbito matrimonial en 1 Co 7:5.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63168, 'spa', 'Oficio apostólico', 'El oficio y comisión del apostolado otorgado por Dios, que designa el ministerio autoritativo de quienes Cristo envió para proclamar el evangelio y establecer la iglesia. Nombra la vacante de Judas (Hch 1:25), el llamado de Pablo por gracia (Rom 1:5), su esfera entre los gentiles (Gál 2:8) y la confirmación corintia de su ministerio (1 Cor 9:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63169, 'spa', 'apóstol, enviado', 'Persona comisionada y enviada con autoridad delegada, especialmente uno de los representantes autorizados de Cristo. El término abarca a los Doce (Mt 10:2; Mr 3:14), a Pablo y a emisarios eclesiales más amplios. El uso del griego clásico como embajador o comandante naval subraya el peso de la delegación oficial. Toda tradición de traducción importante conserva el término como cuasi-transliteración, señalando su estatus singular en el vocabulario cristiano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63177, 'spa', 'Apartarse, rechazar', 'Apartarse de una persona, autoridad o verdad, implicando abandono personal o comunitario. Es el uso dominante en el Nuevo Testamento (5 ocurrencias), abarcando la desercion de los creyentes de Asia (2 Ti 1:15), audiencias que se apartan de la sana doctrina hacia fabulas (2 Ti 4:4), y quienes atienden a fabulas judaicas en vez de la verdad (Tit 1:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63179, 'spa', 'Apartar el pecado', 'Dios como agente que aparta la impiedad o la maldad de un pueblo. En Hechos 3:26, Pedro proclama que Dios levanto a su siervo ''para apartaros de vuestras maldades,'' mientras que en Romanos 11:26 Pablo cita Isaias 59:20: ''vendra el Libertador y apartara la impiedad de Jacob.'' El objeto aqui es el pecado mismo, no las personas, lo que constituye un sentido teologico distintivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63180, 'spa', 'Extraviar, pervertir', 'Extraviar o pervertir a otros, desviando a un grupo de su debida lealtad. Se usa una vez en Lucas 23:14, donde el Sanedrin acusa a Jesus ante Pilato de estar ''pervirtiendo'' al pueblo. La acusacion lo presenta como un subversivo politico, aunque la ironia narrativa de Lucas muestra que el cargo es falso. Este sentido causativo trata al pueblo como objeto que esta siendo desviado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63183, 'spa', 'Devolver, restituir', 'Devolver o restituir un objeto fisico a su lugar. En Mateo 26:52, Jesus dice a Pedro que ''devuelva'' su espada a la vaina. Es el sentido mas concreto y espacial del verbo, desprovisto de matices metaforicos o teologicos. La forma imperativa subraya la inmediata reversion fisica de una accion recien ejecutada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63187, 'spa', 'Expulsado de sinagoga', 'Exclusivamente joánico, designa la exclusión formal de la comunidad sinagogal por confesar a Jesús. Juan 9:22 explica el acuerdo de los líderes judíos de hacer «expulsado de la sinagoga» (ἀποσυνάγωγον) a quien confesara a Cristo como Mesías. Juan 12:42 señala que muchos líderes creyeron pero no lo confesaban por temor a ser expulsados (ἀποσυνάγωγοι). Juan 16:2 predice que los discípulos serán excluidos de las sinagogas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63188, 'spa', 'Despedirse, decir adiós', 'Despedirse, decir adiós, tomar licencia de una persona antes de partir. Este es el sentido primario y más frecuente (5 de 6 ocurrencias). Pablo lo emplea en varios momentos de sus viajes (Hechos 18:18, 18:21; 2 Corintios 2:13), y Jesús se despide de la multitud (Marcos 6:46). Las traducciones al español como ''despidiéndose de'' expresan naturalmente este acto social de separación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63191, 'spa', 'Renunciar, abandonar', 'Renunciar o abandonar posesiones y apegos — una extensión metafórica de ''despedirse'' dirigida a cosas en lugar de personas. En Lucas 14:33, Jesús declara que quien no ''se despide'' (es decir, renuncia) de todas sus posesiones no puede ser su discípulo. La misma forma griega (ἀποτάσσεται) que en otros contextos significa ''decir adiós'' aquí adquiere la fuerza de una renuncia definitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63192, 'spa', 'Culminación de procesos', 'Se usa para procesos que alcanzan su culminación prevista: el ministerio terrenal de Jesús (Lucas 13:32) y la trayectoria mortal del pecado (Santiago 1:15). Ambos pasajes enfatizan la terminación temporal: Jesús ''al tercer día'', el pecado cuando está ''plenamente desarrollado''. El participio perfecto pasivo en Lucas sugiere un estado de terminación, mientras el presente activo en Santiago indica cumplimiento continuo del propósito del pecado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63193, 'spa', 'Despojarse, desechar', 'Despojarse o dejar a un lado en sentido figurado: desechar habitos pecaminosos, cargas morales o el viejo hombre como quien se quita una vestidura. Pablo exhorta a ''despojaros'' del viejo hombre (Ef 4:22), a dejar la mentira (Ef 4:25) y a desechar la ira, la malicia y la calumnia (Col 3:8). Hebreos 12:1 llama a despojarnos de todo peso y del pecado que nos enreda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63194, 'spa', 'Depositar, colocar', 'Depositar o colocar fisicamente un objeto en un lugar determinado. Los testigos de la lapidacion de Esteban pusieron (ἀπέθεντο) sus vestiduras a los pies de un joven llamado Saulo (Hch 7:58), y Herodes mando prender a Juan y lo puso (ἀπέθετο) en la carcel (Mt 14:3). Este sentido concreto y espacial contrasta con el uso figurado predominante del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63201, 'spa', 'Sacudir con gesto simbólico', 'Ambas instancias neotestamentarias involucran gestos físicos simbólicos o dramáticos: sacudir el polvo como testimonio profético de rechazo (Lucas 9:5) y sacudir una serpiente mortal (Hechos 28:5). Las glosas multilingües preservan uniformemente la acción física de sacudir/desprenderse. Curiosamente, el término aparece en el dominio de Actitudes/Emociones a pesar de su naturaleza física, quizás porque sacudir el polvo comunica desdén o desaprobación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63204, 'spa', 'Severidad divina', 'Aparece exclusivamente en Romanos 11:22 donde Pablo contrasta la bondad divina (χρηστότης) con la severidad divina. El contexto involucra a Dios cortando a Israel infiel del olivo, haciendo la severidad tanto metafórica (juicio) como conectada al corte literal. La asignación al dominio de Plantas/Agricultura es desconcertante pero puede reflejar la metáfora hortícola del capítulo (podar ramas).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63205, 'spa', 'Reprensión severa', 'Ambas ocurrencias involucran disciplina apostólica: el ejercicio potencialmente severo de autoridad de Pablo (2 Cor 13:10) e instrucción a Tito de reprender severamente (Tit 1:13). El adverbio modifica verbos de reprensión/corrección, enfatizando modo en lugar de contenido. La ubicación en el dominio de Poder/Fuerza refleja que la reprensión severa es ejercicio de autoridad. El francés preserva el término griego directamente, mientras otros idiomas usan equivalentes nativos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63208, 'spa', 'Llevar, transportar', 'Llevar, transportar o conducir de un lugar a otro. El término abarca la remoción física (Marcos 15:1, llevando a Jesús ante Pilato; Hechos 19:12, llevando paños de Pablo a los enfermos), el transporte angélico póstumo (Lucas 16:22, Lázaro llevado al seno de Abraham), el envío práctico (1 Corintios 16:3, transportando la ofrenda) y la traslación visionaria por el Espíritu (Apocalipsis 17:3; 21:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63213, 'spa', 'Escapar de corrupción', 'Las tres apariciones neotestamentarias en 2 Pedro describen el escape de la corrupción moral y espiritual. 2 Pedro 1:4 celebra las promesas divinas que permiten escapar (ἀποφυγόντες) de la corrupción mundana causada por la concupiscencia. 2 Pedro 2:18 describe a falsos maestros que seducen a quienes apenas están «escapando» (ἀποφεύγοντας) del camino del error. 2 Pedro 2:20 advierte sobre quienes, «habiendo escapado» (ἀποφυγόντες) la contaminación mediante el conocimiento de Cristo, vuelven a enredarse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63214, 'spa', 'Declaración inspirada', 'Empleado en Hechos para declaraciones autoritativas, inspiradas o audaces. Hechos 2:4 describe a los creyentes llenos del Espíritu que comienzan a «proclamar» (ἀποφθέγγεσθαι) en otras lenguas, una expresión sobrenatural. Hechos 2:14 muestra a Pedro poniéndose de pie para «declarar» (ἀπεφθέγξατο) a la multitud con autoridad apostólica. Hechos 26:25 presenta a Pablo defendiendo su cordura, diciendo que «pronuncia» (ἀποφθέγγομαι) palabras sobrias y verdaderas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63217, 'spa', 'Partir o retirarse', 'Expresa partida o retirada en contextos variados. Mateo 7:23 registra el veredicto escatológico de Jesús: «Apartaos» (ἀποχωρεῖτε) de mí, obradores de maldad. Lucas 9:39 describe un espíritu que apenas «se aparta» (ἀποχωρεῖ) del muchacho tras una violenta manifestación. Hechos 13:13 narra que Pablo «partió» (ἀποχωρήσας) de Perga. El verbo abarca desde la separación forzada hasta la partida voluntaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63218, 'spa', 'Separación pasiva', 'Las dos ocurrencias muestran aplicaciones diferentes de separación: el apartamiento relacional entre colaboradores (Hechos 15:39) y la división cósmica de los cielos (Apocalipsis 6:14). Ambas son pasivas: la separación les ocurre a los sujetos en lugar de ser elegida activamente. La evidencia multilingüe usa consistentemente vocabulario de separación, con alemán y francés preservando formas de la raíz griega, sugiriendo reconocimiento de su alcance técnico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63222, 'spa', 'Irreprochable, sin tropiezo', 'Designa una conducta intachable que evita causar ofensa o tropiezo. Hechos 24:16 muestra el compromiso de Pablo de mantener una conciencia «sin ofensa» (ἀπρόσκοπον) ante Dios y los hombres. Primera Corintios 10:32 ordena no ser «tropiezo» (ἀπρόσκοποι) para ningún grupo. Filipenses 1:10 expresa la esperanza de que los creyentes sean «irreprochables» (ἀπρόσκοποι) en el día de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63225, 'spa', 'tocar físicamente para sanar', 'tocar físicamente para sanar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63232, 'spa', 'tocar para dañar o afectar', 'tocar para dañar o afectar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63237, 'spa', 'tocar como contacto prohibido', 'tocar como contacto prohibido');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63242, 'spa', 'Encender, prender', 'Encender, prender o avivar, dicho de lámparas y fuegos. Las cinco apariciones neotestamentarias involucran el acto físico de producir luz o fuego. Lc 8:16 y 11:33 emplean la imagen de encender una lámpara en la enseñanza de Jesús sobre no esconder la luz. Lc 15:8 describe a la mujer encendiendo una lámpara para buscar su moneda perdida, un detalle cotidiano que da vida a la parábola. Lc 22:55 registra cómo se prendió fuego en el patio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63244, 'spa', 'Rechazar, repudiar', 'Empujar o apartar con fuerza, usado casi enteramente en sentido metafórico para rechazar, repudiar o desechar algo valioso. En Hechos 7:27 y 7:39, Israel rechaza a Moisés tanto física como espiritualmente; en Hechos 13:46, la audiencia de la sinagoga desecha la palabra de Dios. La pregunta retórica de Pablo en Romanos 11:1-2 — ¿ha desechado Dios a su pueblo? — emplea el mismo verbo para negar tal posibilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63248, 'spa', 'Destrucción, perdición o ruina total — especialmente en contextos escatológicos ', 'Destrucción, perdición o ruina total — especialmente en contextos escatológicos y teológicos. Designa la pérdida final e irreversible de personas bajo el juicio divino. Jesús contrasta el camino angosto que lleva a la vida con el camino ancho que lleva a la ἀπώλεια (Mt 7:13); Judas es el ''hijo de perdición'' (Jn 17:12); Pablo describe ''vasos de ira preparados para destrucción'' (Ro 9:22). El español alterna reveladoramente entre ''destrucción'' y ''perdición'', subrayando tanto la aniquilación como el estado de estar irremediablemente perdido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63251, 'spa', 'Desperdicio, derroche o pérdida innecesaria de algo valioso', 'Desperdicio, derroche o pérdida innecesaria de algo valioso. Aparece únicamente en los relatos sinópticos de la unción en Betania (Mt 26:8; Mc 14:4), donde los discípulos protestan por el derramamiento de perfume costoso calificándolo de ''desperdicio''. El español ''desperdicio'' y ''pérdida'' distinguen claramente este uso del sentido escatológico. La misma raíz que en otros pasajes designa la perdición eterna aquí nombra la percepción de extravagancia material.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63257, 'spa', 'entonces, pues, por tanto', 'Conjunción ilativa que significa «entonces», «pues», «por tanto», extrayendo una conclusión lógica de la evidencia o el argumento previo. Abrumadoramente dominante (47 de 48 ocurrencias), aparece en la enseñanza de Jesús (Mt 12:28; 17:26) y satura las epístolas de Pablo, especialmente Romanos (Ro 5:18; 7:3; 8:1). Todas las traducciones importantes convergen: «pues/entonces» (esp.), «donc» (fr.), «also» (al.).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63265, 'spa', '¿acaso? (interrogativo)', 'Partícula interrogativa (acentuada ἆρα) que introduce una pregunta teñida de duda o que espera respuesta negativa. Atestiguada solo en Hechos 8:30, donde Felipe pregunta al eunuco etíope si verdaderamente comprende el rollo de Isaías. El español «acaso» captura la cualidad tentativa e indagatoria que distingue este raro uso interrogativo del sentido ilativo habitual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63266, 'spa', 'Interrogación expectante', 'Partícula interrogativa que introduce preguntas marcadas por incertidumbre, esperanza o expectativa ansiosa sobre un resultado desconocido. En Marcos 11:13 enmarca el acercamiento de Jesús a la higuera (''si acaso hallaría algo''), y en Lucas 18:8 colorea la pregunta sobre la fe al retorno del Hijo del Hombre. Hechos 17:27 expresa la intención divina de que la humanidad busque a Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63267, 'spa', 'Región geográfica', 'Ambas ocurrencias en Gálatas conectan Arabia con ubicaciones significativas en la teología de Pablo: su retiro post-conversión (1:17) y la geografía del pacto sinaítico (4:25). La última referencia es particularmente significativa ya que Pablo ubica el monte Sinaí ''en Arabia'', mostrando que su entendimiento geográfico difería de la tradición cristiana posterior que ubicó el Sinaí en la península moderna del Sinaí. Todos los testigos lingüísticos transliteran uniformemente el nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63268, 'spa', 'Nombre propio genealógico', 'El nombre propio Aram (forma griega del hebreo Ram), que identifica a un hombre en la ascendencia de Jesús como hijo de Hezrón y padre de Aminadab en la tribu de Judá. Aparece tanto en la genealogía mateana (Matt 1:3-4) como en la lucana (Luke 3:33), aunque esta última presenta notables variantes textuales (Arní, Admín) en las diversas tradiciones manuscritas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63271, 'spa', 'Ocioso, perezoso', 'Ocioso, perezoso, desempleado: describe a personas que no estan ocupadas en trabajo productivo, ya sea por circunstancia o por habito. La parabola de los obreros lo emplea para los trabajadores que estan ociosos en la plaza porque nadie los ha contratado (Mt 20:3, 6). En 1 Timoteo 5:13 las viudas jovenes se vuelven ''ociosas'', y la caracterizacion de los cretenses los llama ''perezosos glotones'' (Tit 1:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63273, 'spa', 'Inutil, vano', 'Descuidado, inutil, que no produce ningun resultado beneficioso: extension de la ociosidad personal a la inutilidad funcional, aplicada a cosas, palabras o realidades abstractas. Jesus advierte que las personas daran cuenta de toda palabra ''ociosa'' (ἀργόν, Mt 12:36), es decir, palabras que no logran nada bueno y pueden causar dano. Santiago declara que la fe sin obras es ''inutil'' (ἀργή, Stg 2:20), pues yace inactiva y no produce fruto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63276, 'spa', 'Hecho de plata', 'Describe objetos de plata en contextos comerciales, domésticos y religiosos. Hechos 19:24 menciona templos «de plata» (ἀργυροῦς) elaborados por artesanos efesios, objetos de comercio y devoción. Segunda Timoteo 2:20 incluye utensilios «de plata» entre los enseres honorables de una casa. Apocalipsis 9:20 condena a quienes adoran ídolos de oro y «de plata» (ἀργυροῦς).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63277, 'spa', 'Plata como metal precioso y, por extensión, monedas de plata o dinero en general', 'Plata como metal precioso y, por extensión, monedas de plata o dinero en general. En el relato de la traición, Judas recibe y devuelve treinta ἀργύρια (Mt 26:15; 27:3, 5, 9). La parábola de los talentos usa la palabra para referirse al capital encomendado (Mt 25:18, 27). Pedro y Pablo rechazan la plata como riqueza mundana (Hch 3:6; 20:33), y 1 Pedro 1:18 contrasta la plata corruptible con la sangre de Cristo. El español ''plata'' abarca tanto el metal como el dinero, reflejando el doble alcance semántico del término griego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63283, 'spa', 'Plata como metal', 'Plata como metal precioso, que aparece en el NT en listas de materiales y sustancias valiosas. Mt 10:9 la coloca junto al oro y el cobre como metales monetarios que los discípulos no debían llevar. Hch 17:29 la emplea en el argumento de Pablo en el Areópago contra la idolatría: lo divino no se asemeja al oro, la plata ni la piedra. 1 Co 3:12 incluye la plata entre los materiales que serán probados por fuego en el día del juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63284, 'spa', 'Colina y tribunal ateniense', 'El Areópago (Ἄρειος Πάγος, ''Colina de Ares''), referido tanto a la colina rocosa al noroeste de la Acrópolis ateniense como al antiguo consejo judicial que allí sesionaba. Las cuatro apariciones neotestamentarias figuran en Acts 17:19-22, donde Pablo es conducido ante este organismo o a este lugar para presentar su mensaje sobre el ''dios no conocido''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63287, 'spa', 'Causar satisfacción o agrado en alguien, actuar de manera que se gane favor o ap', 'Causar satisfacción o agrado en alguien, actuar de manera que se gane favor o aprobación. El verbo implica siempre un esfuerzo intencional dirigido hacia otra persona. En Romanos 8:8 Pablo insiste en que los que viven según la carne no pueden agradar a Dios, mientras que en 1 Corintios 7:33-34 contrasta el agradar al Señor con el agradar al cónyuge. Gálatas 1:10 plantea la disyuntiva con nitidez: ¿busco agradar a los hombres o a Dios? El español ''agradar'' captura fielmente esta dinámica relacional de actuar para satisfacer a otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63296, 'spa', 'Agradable o aceptable', 'Que resulta agradable o aceptable ante alguien, describiendo conductas que reciben aprobación. Jesús lo emplea respecto a su obediencia al Padre (John 8:29), los apóstoles lo usan negativamente para un curso inadecuado (Acts 6:2), 1 John 3:22 lo presenta como norma de vida, y Acts 12:3 muestra su uso político.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63298, 'spa', 'Virtud y excelencia', 'Virtud, excelencia moral o cualidad digna de elogio, que abarca tanto atributos divinos como la aspiración ética humana. Fil 4:8 lo emplea como término síntesis de todo lo moralmente admirable. 1 Pe 2:9 aplica el plural a las «excelencias» de Dios que el pueblo escogido debe proclamar, evocando el uso de la LXX para las maravillas divinas. 2 Pe 1:3 habla de la virtud como don y meta del creyente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63300, 'spa', 'Contar o enumerar', 'Se usa para la numeración divina y la incapacidad humana de contar. Mateo 10:30 y Lucas 12:7 aseguran que los cabellos de la cabeza «están contados» (ἠρίθμηνται/ἠριθμημέναι), en perfecto que subraya el conocimiento pleno y permanente de Dios. Apocalipsis 7:9 presenta lo opuesto: una multitud tan vasta que «contarla» (ἀριθμῆσαι) resultaba imposible para cualquiera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63301, 'spa', 'Un número, cuenta o cantidad numérica, ya sea literal o simbólica', 'Un número, cuenta o cantidad numérica, ya sea literal o simbólica. En Hechos registra el crecimiento cuantificable de la comunidad creyente (Hch 4:4; 6:7; 11:21) y el tamaño de diversos movimientos (Hch 5:36). En Apocalipsis adquiere fuerza simbólica: el número de la bestia (Ap 13:17-18), los 144.000 sellados (Ap 7:4) y las huestes angélicas innumerables (Ap 5:11). Juan 6:10 lo usa para el recuento práctico de los cinco mil. El español ''número'' traduce el término de manera directa y estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63303, 'spa', 'Ciudad judía bíblica', 'Ciudad de Judea identificada como hogar de José, el honorable miembro del consejo que sepultó el cuerpo de Jesús (Matt 27:57; Mark 15:43; Luke 23:51; John 19:38). Tradicionalmente equiparada con Ramataim (1 Sam 1:1), cuna de Samuel. Aparece en los cuatro Evangelios vinculada exclusivamente a la sepultura de Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63304, 'spa', 'Aristarco, compañero de Pablo', 'Aristarco, nombre propio que identifica a un cristiano macedonio de Tesalónica, leal compañero y colaborador de Pablo. Fue arrastrado por la turba en el motín de Éfeso (Hch 19:29) y continuó viajando con Pablo por Macedonia (Hch 20:4) y en el peligroso viaje marítimo a Roma (Hch 27:2). Pablo lo designa «compañero de prisión» (Col 4:10) y «colaborador» (Flm 1:24), señal de su entrega sacrificada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63305, 'spa', 'Comer o almorzar', 'Designa el acto de comer una comida, creando el contexto para interacciones importantes. Lucas 11:37 relata que un fariseo pidió a Jesús que «comiera» (ἀριστήσῃ) con él, dando paso a la controversia sobre el lavamiento ritual. Juan 21:12 presenta a Jesús invitando a los discípulos a «desayunar» (ἀριστήσατε) en la aparición resucitada. Juan 21:15 señala que «cuando hubieron comido» (ἠρίστησαν), Jesús comenzó a interrogar a Pedro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63306, 'spa', 'Lado izquierdo espacial', 'El lado o la mano izquierda, orientación espacial opuesta a la derecha (δεξιός). En Matt 6:3 aparece en la enseñanza sobre la generosidad secreta; en Mark 10:37 designa la posición opuesta a la derecha en la gloria; en Luke 23:33 ubica a un criminal crucificado; y en 2 Cor 6:7 Pablo expresa disposición integral con armas a diestra y siniestra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (63308, 'spa', 'Banquete formal', 'Se refiere a comidas formales en contextos de hospitalidad y parábolas del reino. Mateo 22:4 lo emplea en la parábola del banquete de bodas: «mi banquete» (ἄριστόν) está listo, enfatizando la celebración preparada. Lucas 11:38 sitúa la controversia de Jesús con los fariseos durante la comida (ἀρίστου), donde ritual y relación se confrontan. Lucas 14:12 enseña sobre a quién invitar al dar «un banquete» (ἄριστον).');